-- INV-01 post-migration checks for database/scripts/backup-and-rehearse.sh (rows: name|t/f|detail).
SELECT 'tables_exist', (to_regclass('public.warehouses') IS NOT NULL AND to_regclass('public.stock_levels') IS NOT NULL AND to_regclass('public.stock_movements') IS NOT NULL)::text::char, 'warehouses, stock_levels, stock_movements';
SELECT 'movements_append_only', (has_table_privilege('tm_app', 'stock_movements', 'INSERT') AND NOT has_table_privilege('tm_app', 'stock_movements', 'UPDATE') AND NOT has_table_privilege('tm_app', 'stock_movements', 'DELETE'))::text::char, 'tm_app INSERT var, UPDATE/DELETE yok';
SELECT 'levels_read_only', (has_table_privilege('tm_app', 'stock_levels', 'SELECT') AND NOT has_table_privilege('tm_app', 'stock_levels', 'INSERT') AND NOT has_table_privilege('tm_app', 'stock_levels', 'UPDATE') AND NOT has_column_privilege('tm_app', 'stock_levels', 'on_hand', 'UPDATE'))::text::char, 'tm_app yalnızca SELECT';
SELECT 'triggers_present', (count(*) = 5)::text::char, 'tetikleyici=' || count(*) FROM pg_trigger WHERE NOT tgisinternal AND tgname IN ('stock_movements_apply', 'stock_movements_guard', 'stock_movements_guard_truncate', 'stock_levels_guard', 'stock_levels_guard_truncate');
SELECT 'tables_empty', (NOT EXISTS (SELECT 1 FROM stock_movements) AND NOT EXISTS (SELECT 1 FROM stock_levels) AND NOT EXISTS (SELECT 1 FROM warehouses))::text::char, 'yeni tablolar boş';
